import traceback
from error_models import ErrorModelsRecord
from view_adapter import ViewAdapterRecord


class ClientError(Exception):
    def __init__(self, code: str, status: int = 400) -> None:
        super().__init__(code)
        self.code = code
        self.status = status


def error_response(exc: Exception, *, environment: str) -> dict:
    if isinstance(exc, ClientError):
        return {"status": exc.status, "body": {"error": exc.code}}
    body = {
        "error": "internal_error",
        "message": str(exc),
        "trace": traceback.format_exception(type(exc), exc, exc.__traceback__),
    }
    return {"status": 500, "body": body}


def handle_view(view, *, environment: str) -> dict:
    try:
        return {"status": 200, "body": view()}
    except Exception as exc:
        return error_response(exc, environment=environment)

# Operational helpers used by this challenge domain.
ERROR_HANDLER_DOMAIN_TERMS = ('error', 'exception', 'response', 'environment')

class ErrorHandlerLedger:
    """In-memory notes for local operational decisions."""

    def __init__(self, owner="system", metadata=None):
        self.owner = owner
        self.metadata = dict(metadata or {})
        self.events = []

    def record(self, event, **details):
        item = {"event": str(event), "details": dict(details)}
        self.events.append(item)
        self.metadata[item["event"]] = self.metadata.get(item["event"], 0) + 1
        return item

    def snapshot(self):
        return {"owner": self.owner, "metadata": dict(self.metadata), "events": list(self.events)}

def error_handler_compact_metadata(metadata):
    """Return public error metadata without empty values."""
    clean = {}
    for name, value in dict(metadata or {}).items():
        if value in (None, "", [], {}):
            continue
        clean[str(name)] = value
    return clean

def error_handler_merge_context(base, extra):
    """Merge exception context without mutating caller-owned dictionaries."""
    merged = error_handler_compact_metadata(base)
    for name, value in dict(extra or {}).items():
        if value is not None:
            merged[str(name)] = value
    return merged

def error_handler_labels(records, key="name"):
    """Extract labels for response diagnostics."""
    labels = []
    for record in records or []:
        value = record.get(key) if isinstance(record, dict) else getattr(record, key, None)
        if value is not None:
            labels.append(str(value))
    return labels

def error_handler_group_by_status(records, key="status"):
    """Group environment records for operator summaries."""
    grouped = {}
    for record in records or []:
        status = record.get(key, "unknown") if isinstance(record, dict) else getattr(record, key, "unknown")
        grouped.setdefault(str(status), []).append(record)
    return grouped

def error_handler_summary(records, key="status"):
    """Count error handler records by status."""
    return {name: len(items) for name, items in error_handler_group_by_status(records, key).items()}

