@dataclass
class ErrorModelsRecord:
    identifier: str
    state: str = "new"
    labels: tuple[str, ...] = ()
    metadata: dict[str, Any] = field(default_factory=dict)

    def with_state(self, state: str) -> "ErrorModelsRecord":
        return ErrorModelsRecord(
            identifier=self.identifier,
            state=state,
            labels=self.labels,
            metadata=dict(self.metadata),
        )

    def add_label(self, label: str) -> "ErrorModelsRecord":
        normalized = normalize_label(label)
        labels = tuple(dict.fromkeys((*self.labels, normalized)))
        return ErrorModelsRecord(
            identifier=self.identifier,
            state=self.state,
            labels=labels,
            metadata=dict(self.metadata),
        )


class ErrorModelsLedger:
    def __init__(self) -> None:
        self._records: dict[str, ErrorModelsRecord] = {}

    def save(self, record: ErrorModelsRecord) -> None:
        self._records[record.identifier] = record

    def get(self, identifier: str) -> ErrorModelsRecord | None:
        return self._records.get(identifier)

    def values(self) -> list[ErrorModelsRecord]:
        return list(self._records.values())

    def count_by_state(self, state: str) -> int:
        return sum(1 for record in self._records.values() if record.state == state)


def normalize_label(label: str) -> str:
    cleaned = str(label).strip().lower().replace(" ", "_")
    return cleaned or "unknown"


def parse_positive_int(value: Any, *, field_name: str) -> int:
    try:
        parsed = int(value)
    except (TypeError, ValueError) as exc:
        raise ValueError(f"{field_name} must be an integer") from exc
    if parsed < 0:
        raise ValueError(f"{field_name} must be non-negative")
    return parsed


def stable_partition(records: list[ErrorModelsRecord], state: str) -> tuple[list[ErrorModelsRecord], list[ErrorModelsRecord]]:
    matching: list[ErrorModelsRecord] = []
    remaining: list[ErrorModelsRecord] = []
    for record in records:
        if record.state == state:
            matching.append(record)
        else:
            remaining.append(record)
    return matching, remaining


def summarize(records: list[ErrorModelsRecord]) -> dict[str, int]:
    summary: dict[str, int] = {}
    for record in records:
        summary[record.state] = summary.get(record.state, 0) + 1
    return summary


