from error_handler import ClientError, error_response, handle_view


def test_client_error_shape_is_stable():
    assert error_response(ClientError("bad_request", 422), environment="production") == {"status": 422, "body": {"error": "bad_request"}}


def test_unexpected_error_status_is_500():
    assert error_response(RuntimeError("db down"), environment="production")["status"] == 500


def test_production_body_uses_generic_error():
    assert error_response(RuntimeError("db down"), environment="production")["body"]["error"] == "internal_error"


def test_production_body_does_not_include_trace_key():
    assert "trace" not in error_response(RuntimeError("db down"), environment="production")["body"]


def test_production_body_does_not_include_exception_message():
    assert "db down" not in str(error_response(RuntimeError("db down"), environment="production")["body"])


def test_development_body_keeps_trace_for_debugging():
    assert "trace" in error_response(RuntimeError("db down"), environment="development")["body"]


def test_handle_view_success_returns_payload():
    assert handle_view(lambda: {"ok": True}, environment="production")["body"] == {"ok": True}


def test_handle_view_sanitizes_unexpected_production_exception():
    response = handle_view(lambda: (_ for _ in ()).throw(RuntimeError("secret path")), environment="production")
    assert "secret path" not in str(response["body"])


def test_common_wrong_fix_does_not_hide_client_error_code():
    response = error_response(ClientError("missing_email", 400), environment="production")
    assert response["body"]["error"] == "missing_email"


def test_staging_keeps_diagnostic_message():
    response = error_response(RuntimeError("db down"), environment="staging")
    assert "db down" in response["body"]["message"]
